#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct SegTree {
    int n;
    vector<ll> sum;        
    vector<char> lazy;     
    vector<ll> total_len;  

    SegTree(int _n=0){ init(_n); }
    void init(int _n){
        n = _n;
        sum.assign(4*n, 0);
        lazy.assign(4*n, 0);
        total_len.assign(4*n, 0);
    }
    void build(int node, int l, int r, const vector<ll>& seg_len){
        if(l==r){
            total_len[node] = seg_len[l];
            return;
        }
        int mid=(l+r)/2;
        build(node*2,l,mid,seg_len);
        build(node*2+1,mid+1,r,seg_len);
        total_len[node] = total_len[node*2] + total_len[node*2+1];
    }
    void apply(int node){
        sum[node] = total_len[node];
        lazy[node] = 1;
    }
    void push(int node){
        if(lazy[node]){
            apply(node*2);
            apply(node*2+1);
            lazy[node]=0;
        }
    }

    void update(int node, int l, int r, int ql, int qr){
        if(ql>r || qr<l) return;
        if(ql<=l && r<=qr){
            apply(node);
            return;
        }
        push(node);
        int mid=(l+r)/2;
        update(node*2, l, mid, ql, qr);
        update(node*2+1, mid+1, r, ql, qr);
        sum[node] = sum[node*2] + sum[node*2+1];
    }

    ll query(int node, int l, int r, int ql, int qr){
        if(ql>r || qr<l) return 0;
        if(ql<=l && r<=qr) return sum[node];
        push(node);
        int mid=(l+r)/2;
        return query(node*2, l, mid, ql, qr)
             + query(node*2+1, mid+1, r, ql, qr);
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m; int n;
    if(!(cin >> m >> n)) return 0;
    vector<pair<ll,ll>> seg(n+1);
    vector<ll> coords;
    coords.reserve(2*n + 2);
    for(int i=1;i<=n;i++){
        ll a,b; cin >> a >> b;
        seg[i] = {a,b};
        coords.push_back(a);
        coords.push_back(b+1); 
    }

    sort(coords.begin(), coords.end());
    coords.erase(unique(coords.begin(), coords.end()), coords.end());

    if(coords.size() < 2){
        cout << 0 << "\n";
        return 0;
    }
    int C = (int)coords.size();
    vector<ll> seg_len(C-1);
    for(int i=0;i<C-1;i++){
        seg_len[i] = coords[i+1] - coords[i]; 
    }

    SegTree st(C-1);
    st.build(1, 0, C-2, seg_len);

    int ans = 0;

    for(int i = n; i >= 1; --i){
        ll a = seg[i].first;
        ll b = seg[i].second;

        int l = int(lower_bound(coords.begin(), coords.end(), a) - coords.begin());
        int r = int(lower_bound(coords.begin(), coords.end(), b+1) - coords.begin()) - 1;
        if(l <= r){
            ll already = st.query(1, 0, C-2, l, r);
            if(already == 0){

                ans++;
            }

            st.update(1, 0, C-2, l, r);
        }
    }

    cout << ans;
}